\set ON_ERROR_STOP on
\connect muzhe_chuzhong
BEGIN;
CREATE TEMP TABLE teacher_bio_drafts (
  id text PRIMARY KEY,
  name text NOT NULL,
  credentials text NOT NULL,
  subjects text NOT NULL,
  focus text NOT NULL
) ON COMMIT DROP;
DO $$ BEGIN
  IF (SELECT count(*) FROM teacher_bio_drafts) <> 31 THEN RAISE EXCEPTION '初中部草稿数量不是31'; END IF;
  IF EXISTS (SELECT 1 FROM teacher_bio_drafts d LEFT JOIN "Teacher" t ON t.id = d.id WHERE t.id IS NULL OR t.name <> d.name) THEN RAISE EXCEPTION '初中部教师身份校验失败'; END IF;
  IF EXISTS (SELECT 1 FROM teacher_bio_drafts d WHERE char_length(d.name || '老师，' || d.credentials || '，授课方向为' || d.subjects || '。' || d.focus || '。' || '课堂注重从学生当下的理解程度出发，把概念梳理、典型例题、当堂表达和针对性练习串联起来；对易错点及时复盘，并把下一步训练目标说清楚。教学目标是让学生不仅掌握当前题目的答案，更能讲明白为什么这样做，逐步形成可迁移的解题方法与更稳定的学习节奏。') > 500) THEN RAISE EXCEPTION '初中部简介超过500字'; END IF;
END $$;
UPDATE "Teacher" t SET bio = d.name || '老师，' || d.credentials || '，授课方向为' || d.subjects || '。' || d.focus || '。' || '课堂注重从学生当下的理解程度出发，把概念梳理、典型例题、当堂表达和针对性练习串联起来；对易错点及时复盘，并把下一步训练目标说清楚。教学目标是让学生不仅掌握当前题目的答案，更能讲明白为什么这样做，逐步形成可迁移的解题方法与更稳定的学习节奏。'
FROM teacher_bio_drafts d WHERE t.id = d.id;
COMMIT;

\connect muzhe_gaozhong
BEGIN;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM "Teacher" WHERE id = 'cmqgmp4a20004508l3ug1k1e9' AND name = '李元林') THEN RAISE EXCEPTION '高中部教师身份校验失败'; END IF;
END $$;
UPDATE "Teacher" SET bio = '李元林老师，具备硕士学历背景，就读吉林大学（985工程高校），专业方向为电子信息技术，授课方向为高中数学、物理。课程重视从题目情境中提取变量与条件，把抽象公式转化为能解释、能使用的解题步骤；对函数、力学等综合题，先明确思路，再完成计算与结果检验。课堂会结合学生的理解程度安排例题与变式练习，及时指出概念混淆和过程跳步的问题。教学目标是帮助学生建立更清晰的知识框架，逐步提高独立分析新题、完整表达推理过程的能力。'
WHERE id = 'cmqgmp4a20004508l3ug1k1e9' AND name = '李元林';
COMMIT;
