INSERT INTO teacher_bio_drafts (id, name, credentials, subjects, focus) VALUES
('cmp8e9dd0000c2m5evupootus','任文涛','具备硕士学历背景，就读中北大学，专业方向为新一代电子信息技术；中北大学有“人民兵工第一校”的办学传统','数学、物理、化学','理科教学强调先弄清题目中的条件与数量关系，再选择公式或方法。对于计算、实验与综合题，重视让学生把关键步骤说出来、写完整，减少只会套题型的情况'),
('cmrc04ke801xenroplfoinnjl','任紫莹','具备硕士学历背景，本科毕业于吉林大学（985工程高校）；原有教师资料记载后保研至天津大学（985工程高校）','英语、化学、物理','面对跨学科知识，重视用清晰的概念框架帮助学生区分相似考点。英语关注语境与表达，理科关注现象背后的原理，让练习不止停留在记住答案'),
('cmsfsmp3l0g0wrx2r2e1xr7sj','张佳涵','本科毕业于河北工业大学（211工程高校），专业方向为通信工程','数学、物理','用工程问题中的逻辑分析方式讲解数学和物理，从已知条件、图像和公式含义切入，逐步建立解题路径。对容易跳步的题目，强调过程书写和结果检验'),
('cmr90329v001493eiel6uxr9j','张思雨','具备硕士学历背景，就读西北师范大学','英语','英语课堂重视词汇在语境中的使用，而不只是孤立背诵。围绕阅读定位、句子结构与书面表达组织练习，帮助学生从看懂题目走向说清、写准自己的意思'),
('cmrahmtx1015312ivbh8ugl58','徐家茹','具备硕士学历背景，就读中国矿业大学（北京）（211工程高校）','化学','化学教学从物质性质、反应条件和实验现象之间的联系入手，帮助学生建立知识网络。对方程式、推断题和实验题，注重说明每一步推理依据'),
('cmsfsdzse0fw2rx2r7fnwrhsg','朱梦','具备硕士学历背景，就读河北师范大学，专业方向为应用统计学','数学、语文、生物、化学','跨学科授课重视先识别学生的具体薄弱点，再确定练习重点。数学侧重数据与推理，语文侧重阅读表达，理科侧重概念联系，避免用同一套方法处理不同问题'),
('cmr7t9qj000045covcufimgo2','李佳瑶','具备硕士学历背景，就读华东师范大学（985工程高校）','数学、语文','数学课强调理解条件与推导过程，语文课关注文本线索、观点组织和表达完整度。课堂会把学生已经会的部分与仍有疑问的部分分开处理，便于后续练习更有针对性'),
('cmr8ulaaf000693eidhi8y5q4','李佳蕊','具备硕士学历背景，就读中国石油大学（211工程高校）','语文','语文教学以读懂文章、形成判断、准确表达为主线。通过梳理段落关系和关键词，帮助学生找到阅读题的依据；写作训练则强调先立意、再组织材料、最后打磨语言'),
('cmp8f7zr3000nappdsz9zd75x','李元林','具备硕士学历背景，就读吉林大学（985工程高校），专业方向为电子信息','数学、物理、化学','理科课程重视把抽象概念转化为可分析的步骤。先厘清定义和适用条件，再通过不同难度的例题辨析方法，使学生面对新题时能够主动找条件、画关系、验结果'),
('cmp8f56e3000happdveolclp7','李博航','具备硕士学历背景，就读华中科技大学（985工程高校），专业方向为水利工程','物理、数学','结合工程学中的建模思路讲解物理和数学：先观察情境，再抽取变量、建立关系，最后检查结论是否合理。重视图像、单位和边界条件，帮助学生减少机械套公式'),
('cmr8upujf000e93eiy5dzcgjl','李文泽','具备硕士学历背景，就读河北大学','化学','化学课堂先帮助学生理解实验现象和反应规律，再训练方程式与推断题。遇到知识点混淆时，用对比整理和针对性练习找出区别，力求让学生讲清原因而不是死记结论'),
('cmrai33jw01m712iv1nml3irf','李木夕','具备硕士学历背景，就读天津大学（985工程高校），专业方向为英语','英语','英语学习以听读输入、语境理解和清楚表达为重点。词汇、语法与阅读题相互衔接，课堂练习强调解释选项依据，并把常见失误整理为下一阶段可执行的复习任务'),
('cmp8f6c4w000kappdsrj6lmp7','杨则石','具备硕士学历背景，就读大连理工大学（985工程高校），专业方向为机械工程','数学、物理、化学','用结构化的方式处理理科综合题：先分析对象和条件，再拆分步骤，最后回看结果。对数学计算、物理模型与化学规律分别设置练习重点，帮助学生形成稳定的思考顺序'),
('cms23vgx700008wgol0sqvb2g','毛博远','具备硕士学历背景，就读河海大学（211工程高校），专业方向为应用数学','数学、物理、化学','数学教学强调概念与方法之间的联系，并将这种分析能力迁移到物理、化学题目。课堂重点是让学生说明解题依据、发现错因，再通过相近题检验是否真正掌握'),
('cmr8zxvqn001093ei2cr5uck4','牛钰丹','具备硕士学历背景，就读华北电力大学（211工程高校）','物理、数学','物理和数学课堂重视图像、公式与实际情境之间的对应关系。对于易混淆的概念，先用例子辨析，再让学生独立说明使用条件，逐步提高分析题意和检查结果的能力'),
('cmr7tklzn00095cov8ikq0pte','王天宇','具备硕士学历背景，就读西南大学（211工程高校）','物理、化学','物理、化学的教学重点是从现象回到原理。课堂会把实验、图表和计算题中的关键信息提取出来，帮助学生理解为什么选择某个规律，并用练习巩固推理链条'),
('cms4mure60dse8wgo7uofnz8f','王怡烁','本科毕业于郑州大学（211工程高校），专业方向为翻译','英语、语文','语言类课程强调准确理解与清楚表达。英语阅读与写作关注语境和句子衔接，语文阅读关注信息提取与观点组织；通过口头复述和书面练习，帮助学生把理解转化为表达'),
('cmr8ukeib000293eikk4xkn03','王田雪','具备硕士学历背景，就读江苏师范大学','生物、物理','生物课重视结构、功能与过程之间的联系，物理课重视现象、模型与公式的对应。课堂用图示和分步提问帮助学生看清因果关系，再通过练习检查是否能够独立解释'),
('cmp9n6ork0000hueote2shsil','白婼鑫','本科毕业于西安电子科技大学（211工程高校），专业方向为雷达对抗','化学、物理','理科课堂注重把复杂题目拆成可判断的小问题。物理关注模型与条件，化学关注反应和实验信息；在典型题后加入变式练习，帮助学生辨认方法适用范围'),
('cmp8ecgtc000i2m5ehdt47ul4','胡思同','本科毕业于石家庄铁道大学，专业方向为应用物理学','英语、数学、物理、化学','跨学科授课重视用贴近学生理解的语言讲清难点。理科题目先抓条件与规律，英语学习则重视语境与表达；课堂通过追问思路和当堂练习，发现似懂非懂的环节并及时巩固'),
('cmp8f3vhe000eappdxmz8v5c5','苏智博','具备硕士学历背景，就读中国科学技术大学（985工程高校）相关培养单位，专业方向为计算机科学与技术','数学、物理、化学','理科教学强调严谨的逻辑链条与问题拆解。面对综合题，先明确已知和目标，再逐步建立关系；通过对比不同解法与检查边界条件，帮助学生理解方法而非记住套路'),
('cmrf32hxe0002gymq3u6q5i3w','苏琳曼','具备硕士学历背景，就读华南理工大学（985工程高校），专业方向为外国语言学及应用语言学','英语','英语课堂把词汇、语法、阅读与表达连成完整的学习过程。讲解时关注学生为什么选错、怎样从上下文寻找依据，再通过复述和短写练习巩固语言运用'),
('cmtmhuzu10003gfuaj57ghn1o','范芳菲','本科毕业于河北师范大学，专业方向为国际贸易','英语、化学、数学','授课强调先确认学生当前的知识基础，再分学科设计练习。英语注重语境与表达，数学注重过程推理，化学注重概念辨析；每次练习都尽量回到具体错因'),
('cms5e3iis0fmi8wgomh3o59h6','董士甜','具备硕士学历背景，就读河北师范大学，专业方向为应用化学','物理、化学','理科教学从现象和实验出发，逐步过渡到规律、方程和计算。化学课重视反应条件与证据，物理课重视受力和过程分析，帮助学生在题目变化时保持清晰思路'),
('cmp8f8sbn000qappd0hzjj3k1','袁浩东','本科毕业于武汉理工大学（211工程高校），专业方向为电子信息','数学、英语、物理','数学与物理课程强调概念、图像和计算之间的联系；英语课程关注阅读定位和表达准确性。课堂把大题拆解成可完成的步骤，并用针对性练习帮助学生找出卡点'),
('cmr8un9cy000a93ei6jexlpq7','赵依梦','具备硕士学历背景，就读北京科技大学（211工程高校）','英语','英语教学围绕阅读理解和准确表达展开。词汇放回句子和篇章中理解，语法放在真实表达中练习；对错题重点分析选项依据和思维误区，帮助学生形成可复用的阅读方法'),
('cms23wpb400058wgoacftgdok','陈佳丽','本科毕业于东北大学（985工程高校），专业方向为英语语言文学','英语','英语课堂重视语言基础与阅读能力同步建立。通过词汇语境、长句拆解和段落结构训练，帮助学生看懂材料、定位依据；写作练习关注内容组织与表达准确'),
('cmp8f1djy000bappd21jdet98','陈晓茹','本科毕业于东南大学（985工程高校），专业方向为哲学','语文、英语、政治、历史、地理、生物','文科与综合学科教学重视提问、证据和观点表达。阅读材料先理清概念与线索，再训练学生用自己的话解释；面对史地、生物等知识，强调建立关联而不是零散记忆'),
('cmp8f0hkw0008appdry5o0vr2','陈晓莉','具备硕士学历背景，就读河北师范大学，专业方向为应用心理','英语、语文、生物','教学关注学生的理解节奏与学习习惯。英语和语文强调阅读、复述与表达，生物强调图示与过程理解；通过分步提问和及时反馈，帮助学生辨认已经掌握与仍需练习的部分'),
('cmp8fcqyb000tappd8ppnayim','韩双双','具备硕士学历背景，就读南开大学（985工程高校），专业方向为生物科学','化学、生物','生物课从结构与功能、过程与调控的关系入手，化学课关注现象与反应规律。课堂通过图示、实验信息和典型题串联知识，帮助学生把零散考点组织成可解释的知识网络'),
('cmp8ea70c000f2m5esiqk018e','马韶锟','具备硕士学历背景，就读中国矿业大学（211工程高校），专业方向为选矿工程','数学、物理','数学和物理教学借助工程问题中的条件分析与模型意识。先找核心变量和约束，再选择方法并检验结果；对计算失误与概念混淆分别处理，帮助学生形成更可靠的解题过程');
